#!/usr/bin/env python3
"""
Discard Hold'em bot, v4: an exploitative EV engine with a CFR fallback.

- Hand evaluation: rank-multiset and flush-mask lookup tables built at start-up
  (start-up time is not charged), evaluated in numpy batches.
- Preflop: an offline Monte Carlo table (tools/gen_preflop.py) holding each
  3-card hand's percentile and its equity against random / top 50% / top 25% /
  top 12% ranges. Opening, steal and 3-bet decisions adapt to the opponent's
  raise and fold rates.
- Postflop: Monte Carlo samples of the opponent's hand, weighted by the
  likelihood of its actions. Each kind of action (bet, raise, call, check,
  preflop raise ...) has a strength calibrated from the hands the opponent shows
  down, and its exposed discard is checked against how it was seen to discard.
- Decisions maximise expected chips over check/call/fold and several bet sizes.
  The opponent folds below a strength threshold learned per bet size and raise
  depth; the rest call or re-raise. Checking out of position looks one bet ahead.
- Discard: keep the pair with the highest equity against that range.
- Blueprint: a near-equilibrium strategy trained offline with Monte Carlo CFR on
  a card and bet abstraction (tools/cfr_train.py), embedded in this file. It plays
  preflop and the flop until the opponent is clearly weak, and every street after
  a heavy loss over 200 or more hands of a leg.
- A match is two legs, each played by a fresh process, so the bot never knows the
  match score and simply maximises chips in the leg it is playing.
"""

import base64
import io
import json
import math
import os
import random
import sys
import time
import zlib
from itertools import combinations, permutations

import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
CARD_INDEX = {r + s: 4 * i + j for i, r in enumerate(RANKS) for j, s in enumerate(SUITS)}
CARD_NAME = {v: k for k, v in CARD_INDEX.items()}
RNG = np.random.default_rng()


def log(*args):
    print(*args, file=sys.stderr, flush=True)


# ------------------------------------------------------------- hand evaluator
# A hand value is an int, category << 20 | up to five 4-bit ranks, so larger is
# better. Categories: 0 high card, 1 pair, ..., 4 straight, 5 flush, ..., 8
# straight flush. A card is 4 * rank + suit, rank 0 (deuce) to 12 (ace).

STRAIGHTS = [(0x1F << (h - 4), h) for h in range(12, 3, -1)] + [(0x100F, 3)]


def _straight_high(mask):
    for window, high in STRAIGHTS:
        if (mask & window) == window:
            return high
    return -1


def _enc(cat, ranks):
    value = cat << 20
    for i, r in enumerate(ranks):
        value |= r << (16 - 4 * i)
    return value


def _nonflush_value(cnt):
    """Best non-flush five-card value from a rank-count vector of 5 to 7 cards."""
    desc = [r for r in range(12, -1, -1) if cnt[r]]
    quads = [r for r in desc if cnt[r] == 4]
    trips = [r for r in desc if cnt[r] == 3]
    pairs = [r for r in desc if cnt[r] == 2]
    if quads:
        return _enc(7, [quads[0], next(r for r in desc if r != quads[0])])
    if trips and (len(trips) > 1 or pairs):
        return _enc(6, [trips[0], max(trips[1:] + pairs)])
    high = _straight_high(sum(1 << r for r in desc))
    if high >= 0:
        return _enc(4, [high])
    if trips:
        return _enc(3, [trips[0]] + [r for r in desc if r != trips[0]][:2])
    if len(pairs) >= 2:
        p1, p2 = pairs[:2]
        return _enc(2, [p1, p2] + [r for r in desc if r != p1 and r != p2][:1])
    if pairs:
        return _enc(1, [pairs[0]] + [r for r in desc if r != pairs[0]][:3])
    return _enc(0, desc[:5])


def _build_tables():
    keys, vals = [], []
    cnt = [0] * 13

    def rec(r, total, key):
        if r == 13:
            if total >= 5:
                keys.append(key)
                vals.append(_nonflush_value(cnt))
            return
        for c in range(min(4, 7 - total) + 1):
            cnt[r] = c
            rec(r + 1, total + c, key + c * 5 ** r)
        cnt[r] = 0

    rec(0, 0, 0)
    order = np.argsort(keys)
    nf_keys = np.array(keys, dtype=np.int64)[order]
    nf_vals = np.array(vals, dtype=np.int64)[order]

    flush = np.zeros(8192, dtype=np.int64)    # flush value of a suit's rank mask, 0 if < 5 cards
    sd_outs = np.zeros(8192, dtype=np.int64)  # ranks that would complete a straight
    for m in range(8192):
        high = _straight_high(m)
        if bin(m).count("1") >= 5:
            if high >= 0:
                flush[m] = _enc(8, [high])
            else:
                flush[m] = _enc(5, [r for r in range(12, -1, -1) if m >> r & 1][:5])
        if high < 0:
            outs = 0
            for window, _ in STRAIGHTS:
                miss = window & ~m
                if miss and not miss & (miss - 1):
                    outs |= miss
            sd_outs[m] = bin(outs).count("1")
    return nf_keys, nf_vals, flush, sd_outs


NF_KEYS, NF_VALS, FLUSH, SD_OUTS = _build_tables()
C_POW5 = np.array([5 ** (c >> 2) for c in range(52)], dtype=np.int64)
C_BIT = np.array([1 << (c >> 2) for c in range(52)], dtype=np.int64)
C_SUIT = np.arange(52) & 3
C_SBIT = np.zeros((4, 52), dtype=np.int64)
C_SBIT[C_SUIT, np.arange(52)] = C_BIT


def evaluate(cards):
    """Values of an (N, 5..7) array of cards."""
    best = NF_VALS[np.searchsorted(NF_KEYS, C_POW5[cards].sum(axis=1))]
    for suit in range(4):
        best = np.maximum(best, FLUSH[C_SBIT[suit][cards].sum(axis=1)])
    return best


def keep_score(hole, flop):
    """Heuristic flop strength of keeping `hole` (N, 2) on `flop` (N, 3): made hand plus draws."""
    five = np.concatenate([hole, flop], axis=1)
    v = evaluate(five)
    cat = v >> 20
    score = cat * 169 + ((v >> 16) & 15) * 13 + ((v >> 12) & 15)
    sd = SD_OUTS[np.bitwise_or.reduce(C_BIT[five], axis=1)]
    suits = C_SUIT[five]
    fd = np.zeros(len(v), dtype=bool)
    for suit in range(4):
        fd |= (suits == suit).sum(axis=1) == 4
    bonus = np.where(fd, 220, 0) + np.where(sd >= 2, 150, np.where(sd == 1, 50, 0))
    return score + np.where(cat < 4, bonus, 0)


KEEP_IDX = np.array([[1, 2], [0, 2], [0, 1]])  # row d: the cards kept when discarding card d


def heuristic_keeps(three, flop):
    """For (N, 3) hands on (N, 3) flops: (discard index, score of the kept pair)."""
    scores = np.stack([keep_score(three[:, k], flop) for k in KEEP_IDX], axis=1)
    return scores.argmax(axis=1), scores.max(axis=1)


# ------------------------------------------------------------ preflop table

# BEGIN PREFLOP DATA (generated by tools/gen_preflop.py; do not edit)
PREFLOP_DATA = ""
# END PREFLOP DATA

PRE_COLUMNS = 5  # percentile, equity vs random, vs top 50%, vs top 25%, vs top 12%
PRE_WIDTHS = (1.0, 0.5, 0.25, 0.12)


def _load_preflop():
    lut = np.full((PRE_COLUMNS, 52, 52, 52), 0.5, dtype=np.float32)
    if not PREFLOP_DATA:
        return lut
    raw = np.frombuffer(base64.b64decode(PREFLOP_DATA), dtype=np.uint8)
    raw = raw.reshape(PRE_COLUMNS, -1).astype(np.float32) / 255.0
    combos = np.array(list(combinations(range(52), 3)))
    for p in permutations(range(3)):
        lut[:, combos[:, p[0]], combos[:, p[1]], combos[:, p[2]]] = raw
    return lut


PRE = _load_preflop()


def pre_lookup(hand):
    return [float(x) for x in PRE[:, hand[0], hand[1], hand[2]]]


# ----------------------------------------------------------- Monte Carlo help

def deal(dead, n, k):
    """n rows of k distinct cards not in `dead`."""
    deck = np.array([c for c in range(52) if c not in dead], dtype=np.intp)
    keys = RNG.random((n, deck.size), dtype=np.float32)
    return deck[np.argsort(keys, axis=1)[:, :k]]


def pct_rank(x):
    """Rank of each sample within the batch, scaled to (0, 1)."""
    r = np.empty(x.size)
    r[np.argsort(x, kind="stable")] = np.arange(x.size)
    return (r + 0.5) / x.size


def m_weight(p, m):
    """Likelihood of an action for hands at percentile p, when the hands behind that
    action average percentile m. p ** a has mean (a + 1) / (a + 2) over uniform p."""
    m = min(0.93, max(0.2, m))
    if m >= 0.5:
        return p ** ((2 * m - 1) / (1 - m))
    return (1 - p) ** ((1 - 2 * m) / m)


def showdown(mine, opp):
    return (mine > opp) + 0.5 * (mine == opp)


def wavg(x, w):
    return float((x * w).sum() / max(w.sum(), 1e-12))


def flop_strength_pct(three, flop, n=400):
    """Percentile of a 3-card hand's best keep on `flop` among random 3-card hands."""
    s = deal(set(three) | set(flop), n, 3)
    _, scores = heuristic_keeps(s, np.broadcast_to(np.array(flop), (n, 3)))
    _, mine = heuristic_keeps(np.array([three]), np.array([flop]))
    return float((scores < mine[0]).mean() + 0.5 * (scores == mine[0]).mean())


def made_strength_pct(two, board):
    """Percentile of a 2-card hand on `board` (4 or 5 cards) among all other 2-card hands."""
    deck = [c for c in range(52) if c not in set(two) | set(board)]
    combos = np.array(list(combinations(deck, 2)))
    vals = evaluate(np.concatenate([combos, np.broadcast_to(np.array(board), (len(combos), len(board)))], 1))
    mine = evaluate(np.array([list(two) + list(board)]))[0]
    return float((vals < mine).mean() + 0.5 * (vals == mine).mean())


# --------------------------------------------------------------- action history

def replay(history, me_button):
    """Annotate each history entry as (street, actor, action, facing, size).

    facing: chips the actor had to call. size: for raises, the raise beyond a
    call as a fraction of the pot after that call.
    """
    total = {"me": 1, "opp": 2} if me_button else {"me": 2, "opp": 1}
    street, bet, out = None, None, []
    for e in history:
        if e.get("street") != street:
            street = e.get("street")
            bet = dict(total) if street == "preflop" else {"me": 0, "opp": 0}
        actor = e.get("actor")
        other = "opp" if actor == "me" else "me"
        action = e.get("action")
        facing = bet[other] - bet[actor]
        size = 0.0
        if action in ("call", "raise"):
            amount = e.get("amount", bet[other])
            if action == "raise":
                size = (amount - bet[other]) / max(1, total["me"] + total["opp"] + facing)
            total[actor] += amount - bet[actor]
            bet[actor] = amount
        out.append((street, actor, action, facing, size))
    return out


def pre_situation(prev):
    """Which preflop spot the opponent faced, given the event before its action."""
    if prev is None:
        return "open"  # opponent is the button, first to act
    if prev[1] == "me" and prev[2] == "call":
        return "vs_limp"
    if prev[1] == "me" and prev[2] == "raise":
        return "vs_raise"
    return None


def action_kind(ev):
    """Class of an action for range calibration, or None for folds."""
    street, _, action, facing, size = ev
    if street == "preflop":
        if action == "raise":
            return "pre_raise"
        if action == "call" and facing > 1:
            return "pre_call"
        return "pre_passive" if action in ("call", "check") else None
    if action == "raise":
        return "raise" if facing > 0 else ("bet_big" if size >= 0.6 else "bet_small")
    return action if action in ("call", "check") else None


# --------------------------------------------------------------- opponent model

SIZE_EDGES = (0.45, 0.85, 1.3, 2.5)  # bet / pot bucket edges


def size_offset(x):
    """Prior fold rate for a bet of x times the pot, relative to the overall rate (~2/3 pot)."""
    return min(0.4, max(-0.15, 0.12 * math.log2(max(x, 0.2) / 0.66)))
STRENGTH_PRIORS = {"pre_raise": 0.70, "pre_call": 0.58, "pre_passive": 0.45, "bet_small": 0.64,
                   "bet_big": 0.72, "raise": 0.80, "call": 0.60, "check": 0.42}


def size_bucket(x):
    return sum(x > e for e in SIZE_EDGES)


def raise_kind(prior_raises):
    """Our bet/raise, by how many bets or raises came before it on the street."""
    return ("bet", "raise", "reraise")[min(prior_raises, 2)]


class OppModel:
    def __init__(self):
        # [hits, trials], seeded with priors
        self.pre_raise = {"open": [3.3, 6.0], "vs_limp": [1.8, 6.0], "vs_raise": [0.9, 6.0]}
        self.pre_fold_vs_raise = [2.0, 6.0]
        # Opponent folds to our postflop bet, our raise of its bet, and our re-raise, per street
        # and size bucket. Later streets get their own rates: ranges that called before fold
        # differently from fresh ones.
        self.fold = {st: {k: [[0, 0] for _ in range(len(SIZE_EDGES) + 1)] for k in ("bet", "raise", "reraise")}
                     for st in ("flop", "turn", "river")}
        self.fold_prior = {"bet": 0.36, "raise": 0.28, "reraise": 0.15}
        self.reraise = [1.0, 8.0]  # opponent raises when facing our postflop bet or raise
        self.lead = [2.4, 6.0]       # opponent bets when not facing a bet postflop
        self.lead_size = [2.6, 4.0]  # mean size of those bets, as a fraction of the pot
        # Mean showdown percentile of the hands behind each kind of action.
        self.strength = {k: [m * 4, 4.0] for k, m in STRENGTH_PRIORS.items()}
        self.keep_match = [3.5, 5.0]  # opponent's discard agrees with our heuristic keep

    @staticmethod
    def rate(stat):
        return stat[0] / stat[1]

    def m(self, kind):
        return self.rate(self.strength[kind])

    def fold_prob(self, kind, x, street):
        """Chance the opponent folds to our bet/raise of x times the pot: the rate for this
        kind on all streets, refined by this street's rate, then by this size bucket's."""
        every = [b for st in self.fold.values() for b in st[kind]]
        hits, n = sum(b[0] for b in every), sum(b[1] for b in every)
        overall = (hits + 6 * self.fold_prior[kind]) / (n + 6)
        buckets = self.fold[street][kind]
        hits, n = sum(b[0] for b in buckets), sum(b[1] for b in buckets)
        overall = (hits + 6 * overall) / (n + 6)
        i = size_bucket(x)
        prior = min(0.95, max(0.02, overall + size_offset(x)))
        return (buckets[i][0] + 4 * prior) / (buckets[i][1] + 4)

    def discard_ratio(self):
        """Likelihood of an observed discard that our heuristic would not make, relative to one it would."""
        c = self.rate(self.keep_match)
        return min(1.0, max(0.05, (1 - c) / (2 * c)))

    def update(self, msg, me_button):
        events = replay(msg.get("history") or [], me_button)
        prev, raises, street_now = None, 0, None
        for ev in events:
            street, actor, action, facing, size = ev
            if street != street_now:
                street_now, raises = street, 0
            if actor == "opp":
                if street == "preflop":
                    key = pre_situation(prev)
                    if key:
                        self.pre_raise[key][0] += action == "raise"
                        self.pre_raise[key][1] += 1
                    if key == "vs_raise":
                        self.pre_fold_vs_raise[0] += action == "fold"
                        self.pre_fold_vs_raise[1] += 1
                elif facing == 0:
                    self.lead[0] += action == "raise"
                    self.lead[1] += 1
                    if action == "raise":
                        self.lead_size[0] += min(size, 3.0)
                        self.lead_size[1] += 1
                elif prev and prev[0] == street and prev[1] == "me" and prev[2] == "raise":
                    bucket = self.fold[street][raise_kind(raises - 1)][size_bucket(prev[4])]
                    bucket[0] += action == "fold"
                    bucket[1] += 1
                    self.reraise[0] += action == "raise"
                    self.reraise[1] += 1
            raises += action == "raise"
            prev = ev
        self._calibrate(msg, events)

    def _calibrate(self, msg, events):
        """At showdown, record how strong the opponent's hand was behind each of its actions."""
        if msg.get("result") != "showdown":
            return
        try:
            opp2 = [CARD_INDEX[c] for c in msg.get("opp_hole_cards") or []]
            disc = CARD_INDEX[msg.get("opp_discard")]
            board = [CARD_INDEX[c] for c in msg.get("board") or []]
        except (KeyError, TypeError):
            return
        if len(opp2) != 2 or len(board) != 5:
            return
        three = opp2 + [disc]
        d, _ = heuristic_keeps(np.array([three]), np.array([board[:3]]))
        self.keep_match[0] += int(d[0]) == 2
        self.keep_match[1] += 1
        pct = {}
        for ev in events:
            kind = action_kind(ev) if ev[1] == "opp" else None
            if kind is None:
                continue
            street = ev[0]
            if street not in pct:
                if street == "preflop":
                    pct[street] = float(PRE[0][three[0], three[1], three[2]])
                elif street == "flop":
                    pct[street] = flop_strength_pct(three, board[:3])
                else:
                    pct[street] = made_strength_pct(opp2, board[:4] if street == "turn" else board)
            stat = self.strength[kind]
            stat[0] += pct[street]
            stat[1] += 1

    def pre_width(self, events):
        """Fraction of hands the opponent's preflop raises so far represent."""
        width, prev = 1.0, None
        for ev in events:
            if ev[0] != "preflop":
                break
            if ev[1] == "opp" and ev[2] == "raise":
                key = pre_situation(prev) or "vs_raise"
                width *= min(0.95, self.rate(self.pre_raise[key]))
            prev = ev
        # blend with the strength of raising hands seen at showdown (top-w range has mean 1 - w/2)
        shown = min(1.0, max(0.05, 2 * (1 - self.m("pre_raise"))))
        if width < 1.0:
            width = math.sqrt(width * shown)
        return max(width, 0.03)

    def weights(self, events, street, p):
        """Product of action likelihoods for the opponent's actions on `street`."""
        w = 1.0
        for ev in events:
            if ev[0] == street and ev[1] == "opp":
                kind = action_kind(ev)
                if kind:
                    w = w * m_weight(p, self.m(kind))
        return w


# ---------------------------------------------------------------- CFR strategy
# A near-equilibrium strategy for strong opponents, trained offline by
# tools/cfr_train.py (external-sampling MCCFR in tools/cfr/mccfr.c) on this
# abstraction. Changing anything in this section's abstraction needs a retrain.
#   betting: bets of 1/3, 2/3 and 1 pot, pot-size raises (preflop also 2x pot),
#     all-in; at most 3 sized bets or raises per street (preflop counts the big
#     blind), then all-in only; anything over 60% of the cap becomes all-in.
#   cards, imperfect recall, one bucket per street: preflop percentile; flop
#     best-keep equity vs a random hand, then current strength within it; turn
#     the same for the kept pair; river strength vs a random hand.
#   discard: the keep with the highest equity vs a random hand.
# Opponent sizes outside the abstraction map to neighbouring sizes with the
# randomized pseudo-harmonic mapping (Ganzfried & Sandholm 2013).

CFR_STACK = 200
CFR_BET_FRACS = (0.33, 0.66, 1.0)
CFR_RAISE_FRACS = (1.0,)
CFR_PRE_RAISE_FRACS = (1.0, 2.0)
CFR_MAX_SIZED = 3  # bets/raises per street after which only all-in is offered
CFR_ALLIN_AT = 0.6
CFR_BUCKETS = (120, 60, 60, 60)
CFR_GRID = {1: (15, 4), 2: (15, 4)}  # flop/turn: equity bins x strength bins within each
CFR_LEVELS = 15  # strategy probabilities are stored in steps of 1/15
CFR_PURIFY = 0.05  # actions below this probability are not played
CFR_SAMPLES = 1500
FOLD, CHECK, CALL, RAISE = 0, 1, 2, 3
DECISION, FOLD_END, SHOWDOWN = 0, 1, 2


class CfrTree:
    """The abstract betting tree, numbered depth-first. Seat 0 is the button."""

    def __init__(self):
        self.kind, self.player, self.street, self.child0, self.nact = [], [], [], [], []
        self.offset, self.value = [], []
        self.children, self.act_type, self.act_frac, self.act_allin = [], [], [], []
        self.size = 0  # strategy entries
        self._build(0, [1, 2], [1, 2], 1, 2, 0, [False, False])

    def _new(self, kind, player=-1, street=-1, value=0):
        for lst, v in ((self.kind, kind), (self.player, player), (self.street, street),
                       (self.child0, -1), (self.nact, 0), (self.offset, -1), (self.value, value)):
            lst.append(v)
        return len(self.kind) - 1

    def _build(self, street, bets, comm, raises, last_raise, p, acted):
        o = 1 - p
        to_call = bets[o] - bets[p]
        max_to = min(bets[p] + CFR_STACK - comm[p], bets[o] + CFR_STACK - comm[o])
        pot = comm[0] + comm[1]
        acts = [(FOLD, 0), (CALL, 0)] if to_call > 0 else [(CHECK, 0)]
        if raises < 4 and max_to > bets[o]:
            tos = {max_to}
            if raises < CFR_MAX_SIZED:
                fracs = (CFR_BET_FRACS if to_call == 0 else CFR_PRE_RAISE_FRACS if street == 0
                         else CFR_RAISE_FRACS)
                for f in fracs:
                    to = bets[o] + max(round(f * (pot + to_call)), last_raise, 2)
                    tos.add(max_to if to > CFR_ALLIN_AT * max_to else to)
            acts += [(RAISE, t) for t in sorted(tos)]
        n = self._new(DECISION, p, street)
        self.nact[n] = len(acts)
        self.offset[n] = self.size
        self.size += len(acts) * CFR_BUCKETS[street]
        self.child0[n] = len(self.children)
        self.children += [-1] * len(acts)
        self.act_type += [a for a, _ in acts]
        self.act_frac += [(to - bets[o]) / (pot + to_call) if a == RAISE else 0.0 for a, to in acts]
        self.act_allin += [a == RAISE and to == max_to for a, to in acts]
        for i, (a, to) in enumerate(acts):
            b, c, ac = list(bets), list(comm), list(acted)
            if a == FOLD:
                child = self._new(FOLD_END, value=c[p] if p == 1 else -c[p])  # seat 0's payoff
            elif a == RAISE:
                c[p] += to - b[p]
                b[p], ac[o], ac[p] = to, False, True
                child = self._build(street, b, c, raises + 1, to - bets[o], o, ac)
            else:
                c[p] += b[o] - b[p]
                b[p] = b[o]
                ac[p] = True
                if not (ac[0] and ac[1]):
                    child = self._build(street, b, c, raises, last_raise, o, ac)
                elif street == 3 or CFR_STACK in c:
                    child = self._new(SHOWDOWN, value=c[0])
                else:
                    child = self._build(street + 1, [0, 0], c, 0, 0, 1, [False, False])
            self.children[self.child0[n] + i] = child
        return n

    def arrays(self):
        """int32 node table (kind, player, street, nact, child0, offset, value) and child list."""
        nodes = np.array([self.kind, self.player, self.street, self.nact, self.child0, self.offset,
                          self.value], dtype=np.int32).T
        return np.ascontiguousarray(nodes), np.array(self.children, dtype=np.int32)


def _cfr_sample(dead, k, s, rng):
    """(N, s, k) cards per row avoiding that row's `dead` cards (N, 52 bool)."""
    keys = rng.random((dead.shape[0], s, 52), dtype=np.float32)
    keys[np.broadcast_to(dead[:, None, :], keys.shape)] = 2.0
    return np.argpartition(keys, k, axis=2)[:, :, :k]


def _cfr_dead(*arrays):
    rows = arrays[0].shape[0]
    dead = np.zeros((rows, 52), dtype=bool)
    for a in arrays:
        dead[np.arange(rows)[:, None], a] = True
    return dead


def _cfr_eval(*parts):
    """Evaluate card arrays joined along the last axis (leading axes broadcast)."""
    lead = np.broadcast_shapes(*(p.shape[:-1] for p in parts))
    cards = np.concatenate([np.broadcast_to(p, lead + p.shape[-1:]) for p in parts], -1)
    return evaluate(cards.reshape(-1, cards.shape[-1])).reshape(lead)


def cfr_flop_features(three, flop, s, rng):
    """For (N, 3) hands on (N, 3) flops: equity of the best keep vs a random hand,
    current strength of that keep, and the index of the card to discard."""
    smp = _cfr_sample(_cfr_dead(three, flop), 4, s, rng)
    opp2, runout = smp[:, :, :2], smp[:, :, 2:]
    fl = np.broadcast_to(flop[:, None, :], runout.shape[:2] + (3,))
    opp_v = _cfr_eval(opp2, fl, runout)
    eqs = np.stack([showdown(_cfr_eval(np.broadcast_to(three[:, None, k], opp2.shape), fl, runout), opp_v).mean(1)
                    for k in KEEP_IDX], axis=1)
    disc = eqs.argmax(1)
    kept = three[np.arange(len(three))[:, None], KEEP_IDX[disc]]
    hs = showdown(_cfr_eval(np.broadcast_to(kept[:, None], opp2.shape), fl), _cfr_eval(opp2, fl)).mean(1)
    return eqs.max(1), hs, disc


def cfr_turn_features(two, board, dead, s, rng):
    """(N, 2) kept hands on (N, 4) boards with (N, 2) discards: equity and current strength."""
    smp = _cfr_sample(_cfr_dead(two, board, dead), 3, s, rng)
    opp2, river = smp[:, :, :2], smp[:, :, 2:]
    bd = np.broadcast_to(board[:, None, :], opp2.shape[:2] + (4,))
    mine = np.broadcast_to(two[:, None], opp2.shape)
    eq = showdown(_cfr_eval(mine, bd, river), _cfr_eval(opp2, bd, river)).mean(1)
    hs = showdown(_cfr_eval(mine, bd), _cfr_eval(opp2, bd)).mean(1)
    return eq, hs


def cfr_river_strength(two, board, dead, s, rng):
    opp2 = _cfr_sample(_cfr_dead(two, board, dead), 2, s, rng)
    bd = np.broadcast_to(board[:, None, :], opp2.shape[:2] + (5,))
    return showdown(_cfr_eval(np.broadcast_to(two[:, None], opp2.shape), bd), _cfr_eval(opp2, bd)).mean(1)


def cfr_grid_bucket(eq, hs, eq_edges, hs_edges):
    """Bucket from the equity bin, then the strength bin within it."""
    e = np.searchsorted(eq_edges, eq, side="right")
    h = np.array([np.searchsorted(hs_edges[i], x, side="right") for i, x in zip(e, hs)])
    return e * (hs_edges.shape[1] + 1) + h


def cfr_pre_bucket(three):
    pct = PRE[0, three[:, 0], three[:, 1], three[:, 2]]
    return np.minimum((pct * CFR_BUCKETS[0]).astype(int), CFR_BUCKETS[0] - 1)


# BEGIN CFR DATA (generated by tools/cfr_train.py pack; do not edit)
CFR_DATA = ""
# END CFR DATA


def _load_cfr():
    """(strategy probabilities, bucket edges), or None when no strategy is embedded."""
    if not CFR_DATA:
        return None
    raw = zlib.decompress(base64.b64decode(CFR_DATA))
    data = np.load(io.BytesIO(raw))
    edges = {k: data[k] for k in data.files if k != "strategy"}
    return data["strategy"].astype(np.float32) / CFR_LEVELS, edges


class CfrPlayer:
    """Plays the embedded CFR strategy. `action` returns None when the hand has left
    the abstract tree (the caller then decides by other means)."""

    def __init__(self):
        self.tree = CfrTree()
        try:
            loaded = _load_cfr()
        except Exception as exc:  # the exploit engine alone is far better than crashing
            log(f"CFR load error: {exc!r}")
            loaded = None
        self.ready = loaded is not None and loaded[0].size == self.tree.size
        self.strategy, self.edges = loaded if self.ready else (None, None)
        self.rng = np.random.default_rng()
        self.new_hand()

    def new_hand(self):
        self.cache = {}  # street -> bucket; "discard" -> index of the card to discard
        self.choices = {}  # our raise children and randomized size mappings, by history index

    def bucket(self, street, hole, board, my_disc, opp_disc):
        if street in self.cache:
            return self.cache[street]
        s, rng = CFR_SAMPLES, self.rng
        if street == 0:
            b = int(cfr_pre_bucket(np.array([hole]))[0])
        elif street == 1:
            eq, hs, disc = cfr_flop_features(np.array([hole]), np.array([board[:3]]), s, rng)
            self.cache["discard"] = int(disc[0])
            b = int(cfr_grid_bucket(eq, hs, self.edges["flop_eq"], self.edges["flop_hs"])[0])
        else:
            two, bd, dead = np.array([hole]), np.array([board]), np.array([[my_disc, opp_disc]])
            if street == 2:
                eq, hs = cfr_turn_features(two, bd, dead, s, rng)
                b = int(cfr_grid_bucket(eq, hs, self.edges["turn_eq"], self.edges["turn_hs"])[0])
            else:
                hs = cfr_river_strength(two, bd, dead, s, rng)
                b = int(np.searchsorted(self.edges["river"], hs[0], side="right"))
        self.cache[street] = b
        return b

    def _children(self, node):
        return range(self.tree.child0[node], self.tree.child0[node] + self.tree.nact[node])

    def _map_raise(self, node, frac, allin, key):
        """Abstract child for a real raise of `frac` x pot (pseudo-harmonic, randomized once)."""
        t = self.tree
        opts = [(t.act_frac[i], i) for i in self._children(node) if t.act_type[i] == RAISE]
        if allin or frac >= opts[-1][0]:
            return opts[-1][1]
        if frac <= opts[0][0]:
            return opts[0][1]
        for (a, ia), (b, ib) in zip(opts, opts[1:]):
            if frac <= b:
                p_a = (b - frac) * (1 + a) / ((b - a) * (1 + frac))
                if key not in self.choices:
                    self.choices[key] = random.random()
                return ia if self.choices[key] < p_a else ib
        return opts[-1][1]

    def locate(self, history, button):
        """Walk the abstract tree along the real history; None when off the tree."""
        t, node = self.tree, 0
        me = 0 if button else 1
        street, bets, comm = None, [0, 0], [1, 2]
        for i, e in enumerate(history):
            s = ("preflop", "flop", "turn", "river").index(e["street"])
            if s != street:
                street, bets = s, ([1, 2] if s == 0 else [0, 0])
            seat = me if e["actor"] == "me" else 1 - me
            if t.kind[node] != DECISION or t.player[node] != seat or t.street[node] != s:
                return None
            o = 1 - seat
            to_call = bets[o] - bets[seat]
            if e["action"] == "raise":
                if not any(t.act_type[c] == RAISE for c in self._children(node)):
                    return None
                amount = e["amount"]
                c = self.choices.get(("own", i)) if e["actor"] == "me" else None
                if c is None:
                    max_to = min(bets[seat] + CFR_STACK - comm[seat], bets[o] + CFR_STACK - comm[o])
                    frac = (amount - bets[o]) / max(1, comm[0] + comm[1] + to_call)
                    c = self._map_raise(node, frac, amount >= max_to, ("opp", i))
                comm[seat] += amount - bets[seat]
                bets[seat] = amount
            else:
                want = {"check": CHECK, "call": CALL, "fold": FOLD}.get(e["action"])
                c = next((c for c in self._children(node) if t.act_type[c] == want), None)
                if c is None:
                    return None
                if e["action"] == "call":
                    comm[seat] += bets[o] - bets[seat]
                    bets[seat] = bets[o]
            node = t.children[c]
        return node

    def action(self, req, hole, button, my_disc, opp_disc):
        t = self.tree
        street = ("preflop", "flop", "turn", "river").index(req["street"])
        node = self.locate(req.get("history") or [], button)
        if node is None or t.kind[node] != DECISION or t.street[node] != street:
            return None
        board = [CARD_INDEX[c] for c in req["board"]]
        b = self.bucket(street, hole, board, my_disc, opp_disc)
        na = t.nact[node]
        probs = self.strategy[t.offset[node] + b * na: t.offset[node] + (b + 1) * na].astype(float)
        probs[probs < CFR_PURIFY] = 0.0
        if probs.sum() <= 0:
            return None
        c = t.child0[node] + int(self.rng.choice(na, p=probs / probs.sum()))
        legal = req["legal_actions"]
        if t.act_type[c] == RAISE and "raise" in legal:
            lo, hi = req["min_raise"], req["max_raise"]
            amount = hi if t.act_allin[c] else req["opp_bet"] + round(t.act_frac[c] * (req["pot"] + req["to_call"]))
            amount = max(lo, min(hi, amount))
            if amount > CFR_ALLIN_AT * hi:
                amount = hi
            self.choices[("own", len(req.get("history") or []))] = c
            return {"type": "action", "action": "raise", "amount": int(amount)}
        if t.act_type[c] == FOLD and "fold" in legal:
            return {"type": "action", "action": "fold"}
        return {"type": "action", "action": "call" if "call" in legal else "check"}

    def discard(self, hole, board):
        """Index of the card to discard: the keep with the most equity vs a random hand."""
        if "discard" not in self.cache:
            self.bucket(1, hole, board, None, None)
        return self.cache["discard"]


# ------------------------------------------------------------------------ bot

BET_SIZES = (0.33, 0.5, 0.75, 1.0, 1.5)
MAX_SIZE = {"flop": 1.0, "turn": 1.5, "river": 99.0}  # largest bet / pot considered, all-in included
REALIZE = {"flop": 0.88, "turn": 0.94, "river": 1.0}
REALIZE_SLOPE = {"flop": 0.4, "turn": 0.3, "river": 0.0}


def realize(street, e):
    """Share of its equity a hand keeps when the hand continues to later streets:
    weak hands face more bets and fold, strong ones collect more."""
    return min(1.05, max(0.6, REALIZE[street] + REALIZE_SLOPE[street] * (e - 0.5)))


def top_mask(strength, w, frac):
    """Samples making up the strongest `frac` of the range by weight."""
    order = np.argsort(-strength, kind="stable")
    cw = np.cumsum(w[order])
    keep = cw <= frac * cw[-1]
    keep[0] = True
    mask = np.zeros(strength.size, dtype=bool)
    mask[order[keep]] = True
    return mask


# Mode switch, as insurance only: exploit mode matches or beats the CFR strategy against every
# opponent tested, so we play CFR for the rest of the leg only after a heavy loss, once
# SWITCH_FIRST hands are played (checked again every SWITCH_EVERY).
SWITCH_FIRST, SWITCH_EVERY, SWITCH_RATE = 200, 40, -2.0
# Exploit mode plays the blueprint on BLUEPRINT_STREETS until a clear win rate shows the
# opponent is weak: then the adaptive play's bigger margins are worth more than its soundness.
BLUEPRINT_STREETS = ("preflop", "flop")
PRE_EXPLOIT_FROM, PRE_EXPLOIT_RATE = 60, 3.0
FORCED_MODE = os.environ.get("BOT_MODE")  # local testing only: "exploit" or "cfr"


class Bot:
    def __init__(self):
        self.total_hands = 200
        self.hand_id = 0
        self.net = 0
        self.opp = OppModel()
        self.ms_per_sample = {"flop": 0.004, "later": 0.004}
        self.button = False
        self.hole = []
        self.my_discard = None
        self.opp_discard = None
        self._history = None
        self.cfr = CfrPlayer()
        self.mode = FORCED_MODE or "exploit"
        self.played = 0  # hands this process has seen finish
        self.bank_s = 30.0
        self.low_time = False
        self._warm_up()

    def _warm_up(self):
        """Run each simulation once so the first timed request is not the slowest."""
        hand = [CARD_INDEX[c] for c in ("As", "Kd", "7c")]
        flop = [CARD_INDEX[c] for c in ("Ah", "7d", "2s")]
        for kind, fn, args in (
                ("flop", self.flop_sim, (hand, flop, [])),
                ("later", self.later_sim, (hand[:2], flop + [CARD_INDEX["3c"]], hand[2], CARD_INDEX["Qs"], []))):
            t = time.perf_counter()
            fn(*args, 1000)
            self.ms_per_sample[kind] = (time.perf_counter() - t)
        made_strength_pct(hand[:2], flop + [CARD_INDEX["3c"]])

    # ---- bookkeeping

    def on_message(self, msg):
        t = msg.get("type")
        if t == "init":
            self.total_hands = int(msg.get("total_hands", self.total_hands))
            self.bank_s = float(msg.get("time_bank_ms", 1000 * self.bank_s)) / 1000
        elif t == "new_hand":
            self.hand_id = int(msg.get("hand_id", self.hand_id + 1))
            self.button = msg.get("seat") == "button"
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
            self.my_discard, self.opp_discard, self._history = None, None, None
            self._choose_mode()
            self.cfr.new_hand()
        elif t == "discard_result":
            self.my_discard = CARD_INDEX.get(msg.get("my_discard"))
            self.opp_discard = CARD_INDEX.get(msg.get("opp_discard"))
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
        elif t == "hand_result":
            self.played += 1
            self.net += int(msg.get("net", 0))
            if not self.low_time:
                self.opp.update(msg, self.button)
            if self.hand_id % 100 == 0:
                o = self.opp
                log(f"hand {self.hand_id} net {self.net:+d} {self.mode} | open {o.rate(o.pre_raise['open']):.2f} "
                    f"fold(bet mid) {o.fold_prob('bet', 0.6, 'flop'):.2f}/{o.fold_prob('bet', 0.6, 'river'):.2f} keep_match {o.rate(o.keep_match):.2f} | "
                    + " ".join(f"{k} {o.m(k):.2f}" for k in STRENGTH_PRIORS))

    def _choose_mode(self):
        if FORCED_MODE or self.mode == "cfr" or not self.cfr.ready:
            return
        played = self.played
        if played >= SWITCH_FIRST and played % SWITCH_EVERY == 0 and self.net < SWITCH_RATE * played:
            self.mode = "cfr"
            log(f"hand {self.hand_id}: net {self.net:+d} after {played} hands, switching to the CFR strategy")

    def _hands_left(self):
        return max(1, self.total_hands - self.hand_id + 1)

    def n_samples(self, req, kind, calls_per_hand=4.0):
        left = float(req.get("time_left_ms", 60000))
        if left < 2000:
            return 100
        budget_ms = 0.25 * left / self._hands_left() / calls_per_hand
        return int(max(150, min(5000, budget_ms / max(self.ms_per_sample[kind], 1e-4))))

    def _timed(self, kind, n, fn, *args):
        t = time.perf_counter()
        out = fn(*args, n)
        per = (time.perf_counter() - t) * 1000 / n
        self.ms_per_sample[kind] = 0.8 * self.ms_per_sample[kind] + 0.2 * per
        return out

    # ---- simulations
    # Each returns per-sample showdown results `res` (1 win, 0.5 tie, 0 loss), range
    # weights `w`, and the opponent's current strength percentile among the samples.

    def flop_sim(self, my3, flop, events, n):
        """Holding three cards on the flop. Also returns the equity of each discard choice."""
        s = deal(set(my3) | set(flop), n, 5)
        opp3, runout = s[:, :3], s[:, 3:]
        flop_n = np.broadcast_to(np.array(flop), (n, 3))
        disc, opp_score = heuristic_keeps(opp3, flop_n)
        opp_keep = np.take_along_axis(opp3, KEEP_IDX[disc], axis=1)
        board = np.concatenate([flop_n, runout], axis=1)
        opp_val = evaluate(np.concatenate([opp_keep, board], axis=1))

        strength = pct_rank(opp_score)
        w = self.opp.weights(events, "preflop", PRE[0][opp3[:, 0], opp3[:, 1], opp3[:, 2]])
        w = w * self.opp.weights(events, "flop", strength) * np.ones(n)

        my3 = np.array(my3)
        results = [showdown(evaluate(np.concatenate([np.broadcast_to(my3[k], (n, 2)), board], axis=1)), opp_val)
                   for k in KEEP_IDX]
        eqs = [wavg(r, w) for r in results]
        return results[int(np.argmax(eqs))], w, strength, eqs

    def later_sim(self, my2, board, my_disc, opp_disc, events, n):
        """Turn or river, two cards each, the opponent's discard known."""
        dead = set(my2) | set(board) | {my_disc, opp_disc}
        s = deal(dead, n, 2 + 5 - len(board))
        opp2 = s[:, :2]
        board_n = np.broadcast_to(np.array(board), (n, len(board)))
        full_board = np.concatenate([board_n, s[:, 2:]], axis=1)
        flop_n = board_n[:, :3]
        od = np.full((n, 1), opp_disc)

        w = self.opp.weights(events, "preflop", PRE[0][opp2[:, 0], opp2[:, 1], od[:, 0]]) * np.ones(n)
        kept = keep_score(opp2, flop_n)
        alt = np.maximum(keep_score(np.concatenate([opp2[:, :1], od], axis=1), flop_n),
                         keep_score(np.concatenate([opp2[:, 1:], od], axis=1), flop_n))
        w = w * np.where(kept >= alt, 1.0, self.opp.discard_ratio())
        w = w * self.opp.weights(events, "flop", pct_rank(kept))
        if len(board) == 5:
            turn_val = evaluate(np.concatenate([opp2, board_n[:, :4]], axis=1))
            w = w * self.opp.weights(events, "turn", pct_rank(turn_val))
        street = "turn" if len(board) == 4 else "river"
        strength = pct_rank(evaluate(np.concatenate([opp2, board_n], axis=1)))
        w = w * self.opp.weights(events, street, strength)

        mine = np.broadcast_to(np.array(my2), (n, 2))
        res = showdown(evaluate(np.concatenate([mine, full_board], axis=1)),
                       evaluate(np.concatenate([opp2, full_board], axis=1)))
        return res, w, strength

    # ---- decisions

    @staticmethod
    def _act(action, amount=None):
        msg = {"type": "action", "action": action}
        if amount is not None:
            msg["amount"] = int(amount)
        return msg

    def _raise_to(self, req, amount):
        lo, hi = req["min_raise"], req["max_raise"]
        amount = int(round(max(lo, min(hi, amount))))
        if amount > 0.6 * hi:  # leaving a sliver behind is pointless: shove
            amount = hi
        return self._act("raise", amount)

    def _passive(self, req):
        return self._act("check" if "check" in (req.get("legal_actions") or ()) else "fold")

    def _check_time(self, req):
        """A forfeit is the worst result there is: with the bank nearly gone, stop thinking
        and play instant passive moves for the rest of the match."""
        left = float(req.get("time_left_ms", 1e9))
        self.low_time = self.low_time or left < 1000 + 3 * self._hands_left()
        return self.low_time

    def action(self, req):
        if self._check_time(req):
            return self._passive(req)
        if self.mode == "cfr":
            reply = self.cfr.action(req, self.hole, self.button, self.my_discard, self.opp_discard)
            if reply is not None:
                return reply
        events = replay(req.get("history") or [], self.button)
        street = req["street"]
        if street in BLUEPRINT_STREETS and self.cfr.ready and (
                self.played < PRE_EXPLOIT_FROM or self.net < PRE_EXPLOIT_RATE * self.played):
            reply = self.cfr.action(req, self.hole, self.button, self.my_discard, self.opp_discard)
            if reply is not None:
                return reply
        if street == "preflop":
            return self.preflop(req, events)
        board = [CARD_INDEX[c] for c in req["board"]]
        if street == "flop":
            n = self.n_samples(req, "flop")
            res, w, strength, _ = self._timed("flop", n, self.flop_sim, self.hole, board, events)
        else:
            n = self.n_samples(req, "later")
            res, w, strength = self._timed("later", n, self.later_sim, self.hole, board,
                                           self.my_discard, self.opp_discard, events)
        return self.postflop(req, street, res, w, strength, events)

    def preflop(self, req, events):
        pct, *eq_cols = pre_lookup(self.hole)
        legal, to_call, pot = req["legal_actions"], req["to_call"], req["pot"]
        can_raise = "raise" in legal

        # Steal more from opponents who fold to raises; raise bigger for value against
        # opponents who don't.
        folds = self.opp.rate(self.opp.pre_fold_vs_raise)
        loosen = 0.8 * (folds - 0.33)
        if to_call == 0:  # big blind after a limp
            if can_raise and pct >= min(0.8, max(0.3, 0.70 - loosen)):
                return self._raise_to(req, random.choice((6, 7, 8)) + (2 if folds < 0.15 else 0))
            return self._act("check")

        if not events:  # button, first to act
            if can_raise and pct >= min(0.55, max(0.0, 0.40 - loosen)):
                return self._raise_to(req, 8 if folds < 0.15 and pct >= 0.75 else 6)
            return self._act("call" if pct >= 0.10 else "fold")

        # Facing a raise: equity against the range the opponent's raises represent.
        width = self.opp.pre_width(events)
        logw = np.log(np.array(PRE_WIDTHS))
        eq = float(np.interp(np.log(width), logw[::-1], np.array(eq_cols)[::-1]))
        my_raises = sum(1 for ev in events if ev[1] == "me" and ev[2] == "raise")
        pot_odds = to_call / (pot + to_call)
        big = to_call >= 0.4 * req["my_stack"]
        if can_raise and eq >= 0.58 + 0.04 * my_raises:
            return self._raise_to(req, 3 * req["opp_bet"])
        if eq * (1.0 if big else 0.9) >= pot_odds:
            return self._act("call")
        return self._act("fold")

    def _check_ev(self, events, street, res, w, strength, pot):
        """Checking. In position this ends the street. Out of position the opponent may bet
        (learned rate and size, from the stronger part of its range) and we call or fold."""
        real = realize(street, wavg(res, w))
        if any(ev[0] == street and ev[1] == "opp" for ev in events):
            return wavg(res, w) * real * pot
        b = self.opp.rate(self.opp.lead)
        size = self.opp.rate(self.opp.lead_size)
        w_bet = w * m_weight(strength, self.opp.m("bet_big" if size >= 0.6 else "bet_small"))
        w_chk = w * m_weight(strength, self.opp.m("check"))
        bet = size * pot
        call = wavg(res, w_bet) * real * (pot + 2 * bet) - bet
        return (1 - b) * wavg(res, w_chk) * real * pot + b * max(0.0, call)

    def postflop(self, req, street, res, w, strength, events):
        """Pick the action with the highest expected chips.

        Check/call realise our equity (discounted before the river). Against a bet or
        raise the opponent folds hands below a strength threshold (its learned fold rate
        for that street and size, read as a percentile), so it folds less once earlier
        actions have narrowed its range. The rest continue, and the very strongest re-raise.
        """
        pot, to_call = req["pot"], req["to_call"]
        my_bet, opp_bet, my_stack = req["my_bet"], req["opp_bet"], req["my_stack"]
        e = wavg(res, w)
        real = realize(street, e)
        options = []
        if to_call == 0:
            options.append((self._check_ev(events, street, res, w, strength, pot), self._act("check")))
        else:
            r = 1.0 if to_call >= my_stack else real
            options.append((0.0, self._act("fold")))
            options.append((e * r * (pot + to_call) - to_call, self._act("call")))

        if "raise" in req["legal_actions"]:
            lo, hi = req["min_raise"], req["max_raise"]
            kind = raise_kind(sum(1 for ev in events if ev[0] == street and ev[2] == "raise"))
            q = self.opp.rate(self.opp.reraise)
            amounts = {hi}
            cap = MAX_SIZE[street]
            if hi - opp_bet > cap * (pot + to_call):
                amounts = set()
            for frac in BET_SIZES:
                if frac <= cap:
                    amount = int(round(max(lo, min(hi, opp_bet + frac * (pot + to_call)))))
                    amounts.add(hi if amount > 0.6 * hi else amount)
            for amount in sorted(amounts):
                add, opp_add = amount - my_bet, amount - opp_bet
                cont = strength >= self.opp.fold_prob(kind, opp_add / (pot + to_call), street)
                fold = 1.0 - float(w[cont].sum() / max(w.sum(), 1e-12))
                final = pot + add + opp_add
                if not cont.any():
                    options.append((pot, self._act("raise", amount)))
                    continue
                if amount < hi:
                    raisers = top_mask(strength, w, (1 - fold) * q)
                    callers = cont & ~raisers
                    ev_raised = max(-add, wavg(res[raisers], w[raisers]) * final - add)
                    if callers.any():  # realised against the callers: a weak hand called keeps less
                        eq_c = wavg(res[callers], w[callers])
                        ev_called = eq_c * realize(street, eq_c) * final - add
                    else:
                        ev_called = ev_raised
                    ev_cont = q * ev_raised + (1 - q) * ev_called
                else:
                    ev_cont = wavg(res[cont], w[cont]) * final - add
                options.append((fold * pot + (1 - fold) * ev_cont, self._act("raise", amount)))

        best = max(ev for ev, _ in options)
        close = [a for ev, a in options if ev >= best - 0.01 * pot]
        return random.choice(close)

    def discard(self, req):
        hole = [CARD_INDEX[c] for c in req["hole_cards"]]
        board = [CARD_INDEX[c] for c in req["board"]][:3]
        self.hole = hole
        if self._check_time(req):
            d, _ = heuristic_keeps(np.array([hole]), np.array([board]))
            return {"type": "discard", "card": CARD_NAME[hole[int(d[0])]]}
        if self.mode == "cfr":
            return {"type": "discard", "card": CARD_NAME[hole[self.cfr.discard(hole, board)]]}
        events = replay(self._history or [], self.button)
        n = self.n_samples(req, "flop")
        _, _, _, eqs = self._timed("flop", n, self.flop_sim, hole, board, events)
        return {"type": "discard", "card": CARD_NAME[hole[int(np.argmax(eqs))]]}

    def handle(self, msg):
        """Reply to a request; None for informational messages."""
        t = msg.get("type")
        if t == "action_request":
            self._history = msg.get("history")
            try:
                return self.action(msg)
            except Exception as exc:  # never forfeit over a bug
                log(f"action error: {exc!r}")
                return self._passive(msg)
        if t == "discard_request":
            try:
                return self.discard(msg)
            except Exception as exc:
                log(f"discard error: {exc!r}")
                return {"type": "discard", "card": (msg.get("hole_cards") or ["2s"])[0]}
        try:
            self.on_message(msg)
        except Exception as exc:
            log(f"message error: {exc!r}")
        return None


def main():
    bot = Bot()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        if not isinstance(msg, dict):
            continue
        if msg.get("type") == "match_end":
            break
        reply = bot.handle(msg)
        if reply is not None:
            print(json.dumps(reply), flush=True)


if __name__ == "__main__":
    main()
